using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"🎒 @{userName}'s Eggpack: 🥚 Eggs: 0 | 🎲 D20 Tokens: 0 | 🎰 RRTokens: 0");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Get user data
        int eggs = 0;
        int d20Tokens = 0;
        int rrTokens = 0;

        if (data["users"] != null && data["users"][userId] != null) {
            eggs = (int)(data["users"][userId]["eggs"] ?? 0);
            d20Tokens = (int)(data["users"][userId]["d20Tokens"] ?? 0);
            rrTokens = (int)(data["users"][userId]["rrTokens"] ?? 0);
        }

        CPH.SendMessage($"🎒 @{userName}'s Eggpack: 🥚 Eggs: {eggs} | 🎲 D20 Tokens: {d20Tokens} | 🎰 RRTokens: {rrTokens}");
        return true;
    }
}
